172	/// Helper function to build a new basic block.
173	fn create_new_block<'a>(
174	    program: &'a mut Program,
175	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
176	    name: &str,
177	) -> BasicBlock {
178	    let block = program
179	        .func_mut(my_ir_generator_info.curr_func.unwrap())
180	        .dfg_mut()
181	        .new_bb()
182	        .basic_block(Some(format!("%bb{}_{}", my_ir_generator_info.bb_cnt, name)));
183	    my_ir_generator_info.bb_cnt += 1;
184	    block
185	}
