//! Build a single component into Koopa IR.

use crate::ast_def::declarations::*;
use koopa::ir::values::Aggregate;
use koopa::ir::{builder_traits::*, FunctionData, Program, Type, TypeKind, Value};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable},
    build_shape, create_new_block, create_new_local_value, get_array_type,
    get_new_local_symbol_name, get_valuedata, insert_basic_blocks, insert_local_instructions,
    IRBuildResult, IRBuildable, MyIRGeneratorInfo, SymbolTableEntry,
};

impl IRBuildable for FuncDef {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let FuncDef::Default(btype, ident, params, block) = self;
        if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
            return Err(format!("Duplicate global symbol: {}", ident.content));
        }

        // Collect parameter types.
        let mut params_ty: Vec<Type> = vec![];
        for param in params {
            let FuncFParam::Default(param_btype, _param_ident, shape_exps) = param;
            match shape_exps {
                None => params_ty.push(Type::get(param_btype.content.clone())),
                Some(shape_exps) => {
                    let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
                    params_ty.push(Type::get_pointer(Type::get(get_array_type(
                        param_btype,
                        &shape,
                    ))));
                }
            }
        }
        let ret_is_unit = matches!(btype.content, TypeKind::Unit);

        // Create the function.
        let func_data = FunctionData::new(
            format!("@{}", ident.content),
            params_ty,
            Type::get(btype.content.clone()),
        );
        let func = program.new_func(func_data);
        my_ir_generator_info
            .function_table
            .insert(ident.content.clone(), func);
        my_ir_generator_info.curr_func = Some(func);

        // Create the entry block.
        let entry_block = create_new_block(program, my_ir_generator_info, "entry");
        insert_basic_blocks(program, my_ir_generator_info, [entry_block]);
        my_ir_generator_info.curr_block = Some(entry_block);

        // Create a new symbol table for the function body.
        my_ir_generator_info.symbol_tables.add_new_table();

        // Allocate and store the parameters.
        let param_values = program.func(func).params().clone();
        for (i, param) in params.iter().enumerate() {
            let FuncFParam::Default(param_btype, param_ident, shape_exps) = param;
            let param_ty_kind = match shape_exps {
                None => param_btype.content.clone(),
                Some(shape_exps) => {
                    let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
                    TypeKind::Pointer(Type::get(get_array_type(param_btype, &shape)))
                }
            };
            let alloc = create_new_local_value(program, my_ir_generator_info)
                .alloc(Type::get(param_ty_kind.clone()));
            let alloc_name = get_new_local_symbol_name(my_ir_generator_info, &param_ident.content);
            program
                .func_mut(func)
                .dfg_mut()
                .set_value_name(alloc, Some(alloc_name));
            let store =
                create_new_local_value(program, my_ir_generator_info).store(param_values[i], alloc);
            insert_local_instructions(program, my_ir_generator_info, [alloc, store]);
            my_ir_generator_info.symbol_tables.insert(
                param_ident.content.clone(),
                SymbolTableEntry::Variable(param_ty_kind, alloc),
            );
        }

        // Build the function body.
        let result = block.build(program, my_ir_generator_info)?;

        // If the body does not end with a return statement, add a default one.
        if let IRBuildResult::OK = result {
            let ret_value = match ret_is_unit {
                true => None,
                false => Some(create_new_local_value(program, my_ir_generator_info).integer(0)),
            };
            let ret = create_new_local_value(program, my_ir_generator_info).ret(ret_value);
            insert_local_instructions(program, my_ir_generator_info, [ret]);
        }

        my_ir_generator_info.curr_func = None;
        my_ir_generator_info.curr_block = None;
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for Block {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let Block::Default(stmts) = self;
        let mut block_result = IRBuildResult::OK;
        for stmt in stmts {
            let result = stmt.build(program, my_ir_generator_info)?;
            // Ignore everything after the return statement.
            if let IRBuildResult::EARLYSTOPPING = result {
                block_result = result;
                break;
            }
        }
        my_ir_generator_info.symbol_tables.delete_new_table();
        Ok(block_result)
    }
}

impl IRBuildable for BlockItem {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BlockItem::Decl(decl) => decl.build(program, my_ir_generator_info),
            BlockItem::Stmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

pub enum IRInitValBuildResult {
    Const(i32),
    Var(Value),
    Aggregate(Value),
}

/// Flattens a (possibly nested) aggregate initializer into a flat list of
/// scalar slots, following the C brace-elision rules. `None` slots are
/// zero-initialized.
fn flatten_initval(
    shape: &[usize],
    childs: &[Box<InitVal>],
    offset: usize,
    scalars: &mut Vec<Option<IRInitValBuildResult>>,
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    let total_size: usize = shape.iter().product();
    let sub_size: usize = shape[1..].iter().product();
    let mut pos = 0usize;
    for child in childs {
        match &**child {
            InitVal::Exp(exp) => {
                if pos >= total_size {
                    return Err(format!("Too many initializers: {:?}", child));
                }
                match exp.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        scalars[offset + pos] = Some(IRInitValBuildResult::Const(int))
                    }
                    IRExpBuildResult::Value(value) => {
                        if is_global {
                            return Err(format!(
                                "Non-constant expression '{:?}' in global aggregate initval!",
                                exp
                            ));
                        }
                        scalars[offset + pos] = Some(IRInitValBuildResult::Var(value));
                    }
                }
                pos += 1;
            }
            InitVal::Aggregate(grandchilds) => {
                // Align to the next sub-array boundary.
                if pos % sub_size != 0 {
                    pos = (pos / sub_size + 1) * sub_size;
                }
                if pos >= total_size {
                    return Err(format!("Too many initializers: {:?}", child));
                }
                flatten_initval(
                    &shape[1..],
                    grandchilds,
                    offset + pos,
                    scalars,
                    is_global,
                    program,
                    my_ir_generator_info,
                )?;
                pos += sub_size;
            }
        }
    }
    Ok(())
}

/// Returns the Koopa type of an array with the given shape.
fn type_of_shape(shape: &[usize]) -> Type {
    if shape.len() == 1 {
        Type::get_array(Type::get_i32(), shape[0])
    } else {
        Type::get_array(type_of_shape(&shape[1..]), shape[0])
    }
}

/// Builds a Koopa aggregate value from the flattened scalar slots.
fn scalars_to_aggregate_value(
    shape: &[usize],
    scalars: &[Option<IRInitValBuildResult>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    let new_integer = |int: i32, program: &mut Program, info: &mut MyIRGeneratorInfo| match is_global
    {
        true => program.new_value().integer(int),
        false => create_new_local_value(program, info).integer(int),
    };
    let elems: Vec<Value> = if shape.len() == 1 {
        scalars
            .iter()
            .map(|scalar| match scalar {
                Some(IRInitValBuildResult::Const(int)) => {
                    new_integer(*int, program, my_ir_generator_info)
                }
                Some(IRInitValBuildResult::Var(value)) => *value,
                Some(IRInitValBuildResult::Aggregate(_)) => {
                    unreachable!("Aggregate in scalar slot!")
                }
                None => new_integer(0, program, my_ir_generator_info),
            })
            .collect()
    } else {
        let sub_size: usize = shape[1..].iter().product();
        scalars
            .chunks(sub_size)
            .map(|chunk| {
                scalars_to_aggregate_value(&shape[1..], chunk, is_global, program, my_ir_generator_info)
            })
            .collect()
    };
    // Use `raw` to allow non-constant elements in local aggregates.
    let data = Aggregate::new_data(elems, type_of_shape(shape));
    match is_global {
        true => program.new_value().raw(data),
        false => create_new_local_value(program, my_ir_generator_info).raw(data),
    }
}

/// Builds a new aggregate value from the initializer.
/// Returns the aggregate value and the total number of scalar slots.
fn build_new_aggregate(
    shape: &[usize],
    childs: &[Box<InitVal>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(Value, usize), String> {
    let total_size: usize = shape.iter().product();
    let mut scalars: Vec<Option<IRInitValBuildResult>> = vec![None; total_size];
    flatten_initval(
        shape,
        childs,
        0,
        &mut scalars,
        is_global,
        program,
        my_ir_generator_info,
    )?;
    let value = scalars_to_aggregate_value(shape, &scalars, is_global, program, my_ir_generator_info);
    Ok((value, total_size))
}

/// Generates store instructions that store every element of an aggregate
/// value into the corresponding location of the allocated memory.
fn aggregate_to_store_insts(
    aggr: Value,
    aggr_ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    let aggr_data = get_valuedata(aggr, program, my_ir_generator_info);
    match aggr_data.kind() {
        koopa::ir::ValueKind::Aggregate(aggregate) => {
            let elems = aggregate.elems().clone();
            for (i, elem) in elems.iter().enumerate() {
                let index =
                    create_new_local_value(program, my_ir_generator_info).integer(i as i32);
                let elem_ptr = create_new_local_value(program, my_ir_generator_info)
                    .get_elem_ptr(aggr_ptr, index);
                insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
                let elem_data = get_valuedata(*elem, program, my_ir_generator_info);
                match elem_data.kind() {
                    koopa::ir::ValueKind::Aggregate(_) => {
                        aggregate_to_store_insts(*elem, elem_ptr, program, my_ir_generator_info)?;
                    }
                    _ => {
                        let store = create_new_local_value(program, my_ir_generator_info)
                            .store(*elem, elem_ptr);
                        insert_local_instructions(program, my_ir_generator_info, [store]);
                    }
                }
            }
            Ok(())
        }
        _ => {
            let store = create_new_local_value(program, my_ir_generator_info).store(aggr, aggr_ptr);
            insert_local_instructions(program, my_ir_generator_info, [store]);
            Ok(())
        }
    }
}

impl InitVal {
    fn build(
        &self,
        shape: &[usize],
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRInitValBuildResult, String> {
        let is_global = my_ir_generator_info.curr_func.is_none();
        match self {
            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
                IRExpBuildResult::Value(value) => {
                    if is_global {
                        Err(format!(
                            "Non-constant expression '{:?}' in global variable initval: {:?}",
                            exp, self
                        ))
                    } else {
                        Ok(IRInitValBuildResult::Var(value))
                    }
                }
            },
            InitVal::Aggregate(childs) => {
                if shape.is_empty() {
                    // Brace-enclosed scalar initializer, e.g. `int x = {5};`
                    if childs.len() != 1 {
                        return Err(format!("Invalid scalar initializer: {:?}", self));
                    }
                    return childs[0].build(shape, program, my_ir_generator_info);
                }
                let (value, _) =
                    build_new_aggregate(shape, childs, is_global, program, my_ir_generator_info)?;
                Ok(IRInitValBuildResult::Aggregate(value))
            }
        }
    }
}

impl IRBuildable for Decl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            Decl::ConstDecl(const_decl) => const_decl.build(program, my_ir_generator_info),
            Decl::VarDecl(var_decl) => var_decl.build(program, my_ir_generator_info),
        }
    }
}

/// Checks whether the given symbol is duplicated in the current scope.
fn check_duplicate_symbol(my_ir_generator_info: &MyIRGeneratorInfo, name: &String) -> bool {
    match my_ir_generator_info.curr_func {
        None => my_ir_generator_info.check_duplicate_global_symbol(name),
        Some(_) => my_ir_generator_info
            .symbol_tables
            .symbol_tables
            .last()
            .unwrap()
            .contains_key(name),
    }
}

/// Allocates memory for a variable (global or local) with the given type and
/// optional initializer, and inserts it into the symbol table.
fn build_variable(
    btype: &crate::ast_def::symbols::BType,
    ident: &crate::ast_def::symbols::IDENT,
    shape_exps: &[crate::ast_def::expressions::Exp],
    init_val: Option<&InitVal>,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    if check_duplicate_symbol(my_ir_generator_info, &ident.content) {
        return Err(format!("Duplicate symbol: {}", ident.content));
    }
    let is_global = my_ir_generator_info.curr_func.is_none();
    let shape = build_shape(
        &shape_exps.iter().cloned().collect::<Vec<_>>(),
        program,
        my_ir_generator_info,
    )?;
    let ty_kind = get_array_type(btype, &shape);

    if is_global {
        // Global variable.
        let init_value = match init_val {
            Some(init_val) => match init_val.build(&shape, program, my_ir_generator_info)? {
                IRInitValBuildResult::Const(int) => program.new_value().integer(int),
                IRInitValBuildResult::Aggregate(value) => value,
                IRInitValBuildResult::Var(_) => {
                    return Err(format!(
                        "Global variable '{}' must be initialized with a constant!",
                        ident.content
                    ))
                }
            },
            None => program.new_value().zero_init(Type::get(ty_kind.clone())),
        };
        let global_alloc = program.new_value().global_alloc(init_value);
        program.set_value_name(global_alloc, Some(format!("@{}", ident.content)));
        my_ir_generator_info.symbol_tables.insert(
            ident.content.clone(),
            SymbolTableEntry::Variable(ty_kind, global_alloc),
        );
    } else {
        // Local variable.
        let alloc = create_new_local_value(program, my_ir_generator_info)
            .alloc(Type::get(ty_kind.clone()));
        let alloc_name = get_new_local_symbol_name(my_ir_generator_info, &ident.content);
        program
            .func_mut(my_ir_generator_info.curr_func.unwrap())
            .dfg_mut()
            .set_value_name(alloc, Some(alloc_name));
        insert_local_instructions(program, my_ir_generator_info, [alloc]);
        my_ir_generator_info.symbol_tables.insert(
            ident.content.clone(),
            SymbolTableEntry::Variable(ty_kind, alloc),
        );
        if let Some(init_val) = init_val {
            match init_val.build(&shape, program, my_ir_generator_info)? {
                IRInitValBuildResult::Const(int) => {
                    let int_value =
                        create_new_local_value(program, my_ir_generator_info).integer(int);
                    let store =
                        create_new_local_value(program, my_ir_generator_info).store(int_value, alloc);
                    insert_local_instructions(program, my_ir_generator_info, [store]);
                }
                IRInitValBuildResult::Var(value) => {
                    let store =
                        create_new_local_value(program, my_ir_generator_info).store(value, alloc);
                    insert_local_instructions(program, my_ir_generator_info, [store]);
                }
                IRInitValBuildResult::Aggregate(aggr) => {
                    aggregate_to_store_insts(aggr, alloc, program, my_ir_generator_info)?;
                }
            }
        }
    }
    Ok(())
}

impl IRBuildable for ConstDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let ConstDecl::Default(btype, const_defs) = self;
        for const_def in const_defs {
            let ConstDef::Default(ident, shape_exps, init_val) = const_def;
            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            if shape.is_empty() {
                // Scalar constant.
                if check_duplicate_symbol(my_ir_generator_info, &ident.content) {
                    return Err(format!("Duplicate symbol: {}", ident.content));
                }
                match init_val.build(&shape, program, my_ir_generator_info)? {
                    IRInitValBuildResult::Const(int) => {
                        my_ir_generator_info.symbol_tables.insert(
                            ident.content.clone(),
                            SymbolTableEntry::Constant(btype.content.clone(), int),
                        );
                    }
                    _ => {
                        return Err(format!(
                            "Constant '{}' must be initialized with a constant expression!",
                            ident.content
                        ))
                    }
                }
            } else {
                // Constant array: build it like a variable with a constant initializer.
                build_variable(
                    btype,
                    ident,
                    shape_exps,
                    Some(init_val),
                    program,
                    my_ir_generator_info,
                )?;
            }
        }
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for VarDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let VarDecl::Default(btype, var_defs) = self;
        for var_def in var_defs {
            let VarDef::Default(ident, shape_exps, init_val) = var_def;
            build_variable(
                btype,
                ident,
                shape_exps,
                init_val.as_ref(),
                program,
                my_ir_generator_info,
            )?;
        }
        Ok(IRBuildResult::OK)
    }
}

