/// Builds a Koopa aggregate value from the flattened scalar slots.
/// All the scalar slots must be constant (or zero-initialized).
fn scalars_to_aggregate_value(
    shape: &[usize],
    scalars: &[Option<IRInitValBuildResult>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    let new_integer = |int: i32, program: &mut Program, info: &mut MyIRGeneratorInfo| match is_global
    {
        true => program.new_value().integer(int),
        false => create_new_local_value(program, info).integer(int),
    };
    let elems: Vec<Value> = if shape.len() == 1 {
        scalars
            .iter()
            .map(|scalar| match scalar {
                Some(IRInitValBuildResult::Const(int)) => {
                    new_integer(*int, program, my_ir_generator_info)
                }
                Some(IRInitValBuildResult::Var(value)) => *value,
                Some(IRInitValBuildResult::Aggregate(_)) => {
                    unreachable!("Aggregate in scalar slot!")
                }
                None => new_integer(0, program, my_ir_generator_info),
            })
            .collect()
    } else {
        let sub_size: usize = shape[1..].iter().product();
        scalars
            .chunks(sub_size)
            .map(|chunk| {
                scalars_to_aggregate_value(&shape[1..], chunk, is_global, program, my_ir_generator_info)
            })
            .collect()
    };
    match is_global {
        true => program.new_value().aggregate(elems),
        false => create_new_local_value(program, my_ir_generator_info).aggregate(elems),
    }
}

/// Emits store instructions that store the flattened scalar slots into the
/// corresponding locations of the allocated memory.
fn emit_scalar_stores(
    shape: &[usize],
    scalars: &[Option<IRInitValBuildResult>],
    ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    if shape.len() == 1 {
        for (i, scalar) in scalars.iter().enumerate() {
            let index = create_new_local_value(program, my_ir_generator_info).integer(i as i32);
            let elem_ptr =
                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, index);
            insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
            let value = match scalar {
                Some(IRInitValBuildResult::Const(int)) => {
                    create_new_local_value(program, my_ir_generator_info).integer(*int)
                }
                Some(IRInitValBuildResult::Var(value)) => *value,
                Some(IRInitValBuildResult::Aggregate(_)) => {
                    unreachable!("Aggregate in scalar slot!")
                }
                None => create_new_local_value(program, my_ir_generator_info).integer(0),
            };
            let store = create_new_local_value(program, my_ir_generator_info).store(value, elem_ptr);
            insert_local_instructions(program, my_ir_generator_info, [store]);
        }
        Ok(())
    } else {
        let sub_size: usize = shape[1..].iter().product();
        for (i, chunk) in scalars.chunks(sub_size).enumerate() {
            let index = create_new_local_value(program, my_ir_generator_info).integer(i as i32);
            let elem_ptr =
                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, index);
            insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
            emit_scalar_stores(&shape[1..], chunk, elem_ptr, program, my_ir_generator_info)?;
        }
        Ok(())
    }
}

