//! Build a single component into Koopa IR.

use crate::ast_def::expressions::*;
use koopa::ir::{builder_traits::*, Program, Type, TypeKind, Value};

use super::{
    create_new_block, create_new_local_value, get_valuedata,
    insert_basic_blocks, insert_local_instructions, MyIRGeneratorInfo, SymbolTableEntry,
};

/// IR expression building result. If the expression is a constant expression, returns the i32 result.
/// Otherwise, returns the Koopa IR Value.
pub enum IRExpBuildResult {
    Const(i32),
    Value(Value),
}
pub trait IRExpBuildable {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String>;
}

impl IRExpBuildable for Exp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            Exp::LOrExp(lor_exp) => lor_exp.build(program, my_ir_generator_info),
        }
    }
}

/// Converts an expression build result into a Koopa IR Value.
fn build_result_to_value(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    match result {
        IRExpBuildResult::Const(int) => {
            create_new_local_value(program, my_ir_generator_info).integer(int)
        }
        IRExpBuildResult::Value(value) => value,
    }
}

/// Tries to fold a binary operation on two constant operands at compile time.
/// Returns `None` if the operation cannot be folded (e.g. division by zero).
fn try_fold_binary(binary_op: koopa::ir::BinaryOp, lhs: i32, rhs: i32) -> Option<i32> {
    use koopa::ir::BinaryOp::*;
    match binary_op {
        Add => Some(lhs.wrapping_add(rhs)),
        Sub => Some(lhs.wrapping_sub(rhs)),
        Mul => Some(lhs.wrapping_mul(rhs)),
        Div => match rhs {
            0 => None,
            _ => Some(lhs.wrapping_div(rhs)),
        },
        Mod => match rhs {
            0 => None,
            _ => Some(lhs.wrapping_rem(rhs)),
        },
        Eq => Some((lhs == rhs) as i32),
        NotEq => Some((lhs != rhs) as i32),
        Lt => Some((lhs < rhs) as i32),
        Gt => Some((lhs > rhs) as i32),
        Le => Some((lhs <= rhs) as i32),
        Ge => Some((lhs >= rhs) as i32),
        And => Some(lhs & rhs),
        Or => Some(lhs | rhs),
        Xor => Some(lhs ^ rhs),
        Shl => Some(lhs.wrapping_shl(rhs as u32)),
        Shr => Some((lhs as u32).wrapping_shr(rhs as u32) as i32),
        Sar => Some(lhs.wrapping_shr(rhs as u32)),
    }
}

fn build_binary_from_build_results(
    result1: IRExpBuildResult,
    result2: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    binary_op: koopa::ir::BinaryOp,
) -> Result<IRExpBuildResult, String> {
    // Constant folding.
    if let (IRExpBuildResult::Const(lhs), IRExpBuildResult::Const(rhs)) = (&result1, &result2) {
        if let Some(folded) = try_fold_binary(binary_op, *lhs, *rhs) {
            return Ok(IRExpBuildResult::Const(folded));
        }
    }
    let lhs = build_result_to_value(result1, program, my_ir_generator_info);
    let rhs = build_result_to_value(result2, program, my_ir_generator_info);
    let binary = create_new_local_value(program, my_ir_generator_info).binary(binary_op, lhs, rhs);
    insert_local_instructions(program, my_ir_generator_info, [binary]);
    Ok(IRExpBuildResult::Value(binary))
}

/// Builds a short-circuit logical expression (`||` or `&&`).
/// `jump_on_true` decides the branch layout: `||` jumps to the end block when
/// the lhs is true, while `&&` jumps to the end block when the lhs is false.
fn build_short_circuit_binary(
    result1: IRExpBuildResult,
    rhs_exp: &impl IRExpBuildable,
    jump_on_true: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<IRExpBuildResult, String> {
    // Allocate a temporary to hold the result.
    let result_ptr = create_new_local_value(program, my_ir_generator_info).alloc(Type::get_i32());

    // Evaluate the lhs and normalize it to 0/1.
    let lhs = build_result_to_value(result1, program, my_ir_generator_info);
    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
    let lhs_ne =
        create_new_local_value(program, my_ir_generator_info).binary(koopa::ir::BinaryOp::NotEq, lhs, zero);
    let store_lhs = create_new_local_value(program, my_ir_generator_info).store(lhs_ne, result_ptr);

    // Create the blocks.
    let rhs_block = create_new_block(program, my_ir_generator_info, "short_circuit_rhs");
    let end_block = create_new_block(program, my_ir_generator_info, "short_circuit_end");
    let (true_bb, false_bb) = match jump_on_true {
        true => (end_block, rhs_block),
        false => (rhs_block, end_block),
    };
    let branch = create_new_local_value(program, my_ir_generator_info).branch(lhs_ne, true_bb, false_bb);
    insert_local_instructions(
        program,
        my_ir_generator_info,
        [result_ptr, lhs_ne, store_lhs, branch],
    );
    insert_basic_blocks(program, my_ir_generator_info, [rhs_block, end_block]);

    // Build the rhs in the rhs block.
    my_ir_generator_info.curr_block = Some(rhs_block);
    let rhs = build_result_to_value(rhs_exp.build(program, my_ir_generator_info)?, program, my_ir_generator_info);
    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
    let rhs_ne =
        create_new_local_value(program, my_ir_generator_info).binary(koopa::ir::BinaryOp::NotEq, rhs, zero);
    let store_rhs = create_new_local_value(program, my_ir_generator_info).store(rhs_ne, result_ptr);
    let jump = create_new_local_value(program, my_ir_generator_info).jump(end_block);
    insert_local_instructions(
        program,
        my_ir_generator_info,
        [rhs_ne, store_rhs, jump],
    );

    // Load the result in the end block.
    my_ir_generator_info.curr_block = Some(end_block);
    let result = create_new_local_value(program, my_ir_generator_info).load(result_ptr);
    insert_local_instructions(program, my_ir_generator_info, [result]);
    Ok(IRExpBuildResult::Value(result))
}

impl IRExpBuildable for LOrExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            LOrExp::LAndExp(exp) => exp.build(program, my_ir_generator_info),
            LOrExp::BinaryLOrExp(exp1, exp2) => {
                let result1 = exp1.build(program, my_ir_generator_info)?;
                // Constant folding.
                if let IRExpBuildResult::Const(lhs) = result1 {
                    if lhs != 0 {
                        // Short-circuit: the rhs is never evaluated.
                        return Ok(IRExpBuildResult::Const(1));
                    }
                    return match exp2.build(program, my_ir_generator_info)? {
                        IRExpBuildResult::Const(rhs) => Ok(IRExpBuildResult::Const((rhs != 0) as i32)),
                        IRExpBuildResult::Value(rhs) => {
                            let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                            let rhs_ne = create_new_local_value(program, my_ir_generator_info)
                                .binary(koopa::ir::BinaryOp::NotEq, rhs, zero);
                            insert_local_instructions(program, my_ir_generator_info, [rhs_ne]);
                            Ok(IRExpBuildResult::Value(rhs_ne))
                        }
                    };
                }
                build_short_circuit_binary(result1, exp2, true, program, my_ir_generator_info)
            }
        }
    }
}

impl IRExpBuildable for LAndExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            LAndExp::EqExp(exp) => exp.build(program, my_ir_generator_info),
            LAndExp::BinaryLAndExp(exp1, exp2) => {
                let result1 = exp1.build(program, my_ir_generator_info)?;
                // Constant folding.
                if let IRExpBuildResult::Const(lhs) = result1 {
                    if lhs == 0 {
                        // Short-circuit: the rhs is never evaluated.
                        return Ok(IRExpBuildResult::Const(0));
                    }
                    return match exp2.build(program, my_ir_generator_info)? {
                        IRExpBuildResult::Const(rhs) => Ok(IRExpBuildResult::Const((rhs != 0) as i32)),
                        IRExpBuildResult::Value(rhs) => {
                            let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                            let rhs_ne = create_new_local_value(program, my_ir_generator_info)
                                .binary(koopa::ir::BinaryOp::NotEq, rhs, zero);
                            insert_local_instructions(program, my_ir_generator_info, [rhs_ne]);
                            Ok(IRExpBuildResult::Value(rhs_ne))
                        }
                    };
                }
                build_short_circuit_binary(result1, exp2, false, program, my_ir_generator_info)
            }
        }
    }
}

impl IRExpBuildable for EqExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            EqExp::RelExp(exp) => exp.build(program, my_ir_generator_info),
            EqExp::BinaryEqExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Eq,
            ),
            EqExp::BinaryUneqExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::NotEq,
            ),
        }
    }
}

impl IRExpBuildable for RelExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            RelExp::AddExp(exp) => exp.build(program, my_ir_generator_info),
            RelExp::BinaryLtExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Lt,
            ),
            RelExp::BinaryGtExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Gt,
            ),
            RelExp::BinaryLeExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Le,
            ),
            RelExp::BinaryGeExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Ge,
            ),
        }
    }
}

impl IRExpBuildable for AddExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            AddExp::MulExp(exp) => exp.build(program, my_ir_generator_info),
            AddExp::BinaryAddExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Add,
            ),
            AddExp::BinarySubExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Sub,
            ),
        }
    }
}

impl IRExpBuildable for MulExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            MulExp::UnaryExp(exp) => exp.build(program, my_ir_generator_info),
            MulExp::BinaryMulExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Mul,
            ),
            MulExp::BinaryDivExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Div,
            ),
            MulExp::BinaryModExp(exp1, exp2) => build_binary_from_build_results(
                exp1.build(program, my_ir_generator_info)?,
                exp2.build(program, my_ir_generator_info)?,
                program,
                my_ir_generator_info,
                koopa::ir::BinaryOp::Mod,
            ),
        }
    }
}

impl IRExpBuildable for UnaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            UnaryExp::PrimaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::PlusUnaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::MinusUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int.wrapping_neg())),
                IRExpBuildResult::Value(value) => {
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let sub = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Sub, zero, value);
                    insert_local_instructions(program, my_ir_generator_info, [sub]);
                    Ok(IRExpBuildResult::Value(sub))
                }
            },
            UnaryExp::NotUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int == 0) as i32)),
                IRExpBuildResult::Value(value) => {
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let eq = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Eq, value, zero);
                    insert_local_instructions(program, my_ir_generator_info, [eq]);
                    Ok(IRExpBuildResult::Value(eq))
                }
            },
            UnaryExp::FuncCall(ident, args) => {
                let func = match my_ir_generator_info.function_table.get(&ident.content) {
                    Some(func) => *func,
                    None => return Err(format!("Undeclared function: {}", ident.content)),
                };
                let func_ty = program.func(func).ty().clone();
                let (params_ty, ret_ty) = match func_ty.kind() {
                    TypeKind::Function(params_ty, ret_ty) => (params_ty.clone(), ret_ty.clone()),
                    _ => return Err(format!("'{}' is not a function!", ident.content)),
                };
                if params_ty.len() != args.len() {
                    return Err(format!(
                        "Function '{}' expects {} arguments, but {} were given!",
                        ident.content,
                        params_ty.len(),
                        args.len()
                    ));
                }
                // Build the arguments and check their types.
                let mut arg_values = vec![];
                for (arg_exp, param_ty) in args.iter().zip(params_ty.iter()) {
                    let arg_value = build_result_to_value(
                        arg_exp.build(program, my_ir_generator_info)?,
                        program,
                        my_ir_generator_info,
                    );
                    let arg_ty = get_valuedata(arg_value, program, my_ir_generator_info)
                        .ty()
                        .clone();
                    if &arg_ty != param_ty {
                        return Err(format!(
                            "Argument type mismatch in call to '{}': expected '{}', got '{}'!",
                            ident.content, param_ty, arg_ty
                        ));
                    }
                    arg_values.push(arg_value);
                }
                let call = create_new_local_value(program, my_ir_generator_info).call(func, arg_values);
                insert_local_instructions(program, my_ir_generator_info, [call]);
                match ret_ty.is_unit() {
                    // Void function calls produce no usable value. Return the call
                    // value anyway; it should only be used as a statement.
                    true => Ok(IRExpBuildResult::Value(call)),
                    false => Ok(IRExpBuildResult::Value(call)),
                }
            }
        }
    }
}

impl IRExpBuildable for PrimaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            PrimaryExp::BracedExp(exp) => exp.build(program, my_ir_generator_info),
            PrimaryExp::Number(number) => number.build(program, my_ir_generator_info),
            PrimaryExp::LVal(lval) => match lval.build(program, my_ir_generator_info)? {
                IRLValBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int)),
                IRLValBuildResult::TempVal(value) => Ok(IRExpBuildResult::Value(value)),
                IRLValBuildResult::Addr(ptr) => {
                    let pointee_ty = match get_valuedata(ptr, program, my_ir_generator_info).ty().kind() {
                        TypeKind::Pointer(base) => base.clone(),
                        _ => return Err("LVal address is not a pointer!".to_string()),
                    };
                    if pointee_ty.is_i32() {
                        // Scalar: load the value.
                        let load = create_new_local_value(program, my_ir_generator_info).load(ptr);
                        insert_local_instructions(program, my_ir_generator_info, [load]);
                        Ok(IRExpBuildResult::Value(load))
                    } else {
                        // Array used as a value: decay to the pointer of its first element.
                        let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                        let decayed =
                            create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, zero);
                        insert_local_instructions(program, my_ir_generator_info, [decayed]);
                        Ok(IRExpBuildResult::Value(decayed))
                    }
                }
            },
        }
    }
}

#[derive(Debug)]
pub enum IRLValBuildResult {
    Const(i32),
    TempVal(Value),
    Addr(Value),
}

impl LVal {
    pub fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRLValBuildResult, String> {
        let LVal::Default(ident, index_exps) = self;
        match my_ir_generator_info.symbol_tables.get(&ident.content) {
            Some(SymbolTableEntry::Variable(_, ptr)) => {
                let ptr = ptr.clone();
                // Build indexes.
                let mut index_values = vec![];
                for exp in index_exps {
                    let build = exp.build(program, my_ir_generator_info)?;
                    index_values.push(match build {
                        IRExpBuildResult::Const(int) => {
                            create_new_local_value(program, my_ir_generator_info)
                                .integer(int)
                        }
                        IRExpBuildResult::Value(value) => value,
                    })
                }
                // Get element.
                let result = get_element_in_ndarray(ptr, &index_values, program, my_ir_generator_info);
                Ok(result)
            }
            Some(SymbolTableEntry::Constant(_lval_type, int)) => Ok(IRLValBuildResult::Const(*int)),
            None => Err(format!("Undeclared LVal symbol: {}", ident.content)),
        }
    }
}

impl IRExpBuildable for Number {
    fn build(
        &self,
        _program: &mut Program,
        _my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            Number::INTCONST(int) => Ok(IRExpBuildResult::Const(*int)),
        }
    }
}

/// This is a LVal Value. It should always be a local Value.
fn get_element_in_ndarray(
    array_or_pointer: Value,
    indexes: &[Value],
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> IRLValBuildResult {
    let mut cur = array_or_pointer;
    for index in indexes {
        let cur_ty = get_valuedata(cur, program, my_ir_generator_info).ty().clone();
        let is_pointer_value = match cur_ty.kind() {
            TypeKind::Pointer(base) => matches!(base.kind(), TypeKind::Pointer(_)),
            _ => false,
        };
        if is_pointer_value {
            // The symbol is a pointer (array parameter): load the pointer
            // first, then advance it with `getptr`.
            let loaded = create_new_local_value(program, my_ir_generator_info).load(cur);
            let advanced =
                create_new_local_value(program, my_ir_generator_info).get_ptr(loaded, *index);
            insert_local_instructions(program, my_ir_generator_info, [loaded, advanced]);
            cur = advanced;
        } else {
            // The symbol is an array: get the element pointer directly.
            let element_ptr =
                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(cur, *index);
            insert_local_instructions(program, my_ir_generator_info, [element_ptr]);
            cur = element_ptr;
        }
    }
    // A pointer symbol with no index applied evaluates to the pointer itself.
    let cur_ty = get_valuedata(cur, program, my_ir_generator_info).ty().clone();
    if let TypeKind::Pointer(base) = cur_ty.kind() {
        if matches!(base.kind(), TypeKind::Pointer(_)) {
            let loaded = create_new_local_value(program, my_ir_generator_info).load(cur);
            insert_local_instructions(program, my_ir_generator_info, [loaded]);
            return IRLValBuildResult::TempVal(loaded);
        }
    }
    IRLValBuildResult::Addr(cur)
}

