/// Writes back (and frees) every register that currently holds a global
/// variable. Used at basic block boundaries.
fn store_global_variables(&mut self) -> Vec<String> {
    let mut codes = vec![];
    for reg in 0..REGISTER_NAMES.len() {
        if let Some(value) = self.register_user[reg] {
            if value.is_global() {
                codes.extend(self.save_register(reg));
            }
        }
    }
    codes
}

/// Writes back (and frees) every register that currently holds a local
/// value (named variables, temporaries, arguments). Used at basic block
/// boundaries.
fn store_local_variables(&mut self) -> Vec<String> {
    let mut codes = vec![];
    for reg in 0..REGISTER_NAMES.len() {
        if let Some(value) = self.register_user[reg] {
            if !value.is_global() {
                codes.extend(self.save_register(reg));
            }
        }
    }
    codes
}

/// Kick the value in a register and store it to memory.
fn save_register(&mut self, reg: usize) -> Vec<String> {
    let user = match self.register_user[reg] {
        Some(user) => user,
        None => return vec![],
    };
    let mut codes = vec![];
    if user.is_global() {
        let value_data = self.program.borrow_value(user).clone();
        if let koopa::ir::ValueKind::GlobalAlloc(_) = value_data.kind() {
            let name = value_data.name().unwrap()[1..].to_string();
            codes.extend(self.store_global(reg, name));
        }
        // Global constants are never modified, so there is no need to save them.
    } else {
        let value_data = self.fd.dfg().value(user).clone();
        match value_data.kind() {
            // Constants do not have a memory location.
            koopa::ir::ValueKind::Integer(_)
            | koopa::ir::ValueKind::ZeroInit(_)
            | koopa::ir::ValueKind::Undef(_) => {}
            _ => {
                if let Some(offset) = self.local_value_location.get(&user) {
                    codes.extend(self.store_with_offset(reg, *offset as isize));
                }
            }
        }
    }
    self.__free_user(reg);
    codes
}

/// Finds a usable register.
/// If all registers are being used, then kicks one.
fn get_tmp_reg(&mut self) -> (usize, Vec<String>) {
    // Prefer a free register.
    for &reg in REGISTER_FOR_TEMP.iter() {
        if self.register_user[reg].is_none() {
            return (reg, vec![]);
        }
    }
    // Otherwise, kick the least recently used register.
    let mut lru_reg = REGISTER_FOR_TEMP[0];
    for &reg in REGISTER_FOR_TEMP.iter() {
        if self.register_used_time[reg] < self.register_used_time[lru_reg] {
            lru_reg = reg;
        }
    }
    let codes = self.save_register(lru_reg);
    (lru_reg, codes)
}

/// Want to visit a value. Make it appear in a register.
fn want_to_visit_value(
    &mut self,
    value: Value,
    do_load: bool,
    use_certain_reg: Option<usize>,
) -> (usize, Vec<String>) {
    let mut codes = vec![];
    // The value is already in a register.
    if let Some(reg) = self.__is_value_in_register(value) {
        match use_certain_reg {
            Some(target) if target != reg => {
                // Move the value to the target register.
                codes.extend(self.save_register(target));
                codes.push(format!(
                    "  mv\t{}, {}",
                    REGISTER_NAMES[target], REGISTER_NAMES[reg]
                ));
                self.__free_user(reg);
                self.__update_user(target, value);
                return (target, codes);
            }
            _ => {
                self.__update_user(reg, value);
                return (reg, codes);
            }
        }
    }
    // Choose a register.
    let reg = match use_certain_reg {
        Some(target) => {
            codes.extend(self.save_register(target));
            target
        }
        None => {
            let (reg, save_codes) = self.get_tmp_reg();
            codes.extend(save_codes);
            reg
        }
    };
    // Load the value into the register.
    if do_load {
        if value.is_global() {
            let value_data = self.program.borrow_value(value).clone();
            match value_data.kind() {
                koopa::ir::ValueKind::Integer(int) => {
                    codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], int.value()))
                }
                koopa::ir::ValueKind::GlobalAlloc(_) => {
                    let name = value_data.name().unwrap()[1..].to_string();
                    codes.extend(self.load_global(reg, name));
                }
                _ => {}
            }
        } else {
            let value_data = self.fd.dfg().value(value).clone();
            match value_data.kind() {
                koopa::ir::ValueKind::Integer(int) => {
                    codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], int.value()))
                }
                _ => {
                    if let Some(offset) = self.local_value_location.get(&value) {
                        codes.extend(self.load_with_offset(reg, *offset as isize));
                    }
                }
            }
        }
    }
    self.__update_user(reg, value);
    (reg, codes)
}

/// Assigns the value of `v1` to `v2`. `v2` should be a global variable or
/// a local variable with a stack location.
fn assign_v1_to_v2(&mut self, v1: Value, v2: Value) -> Vec<String> {
    let (reg1, mut codes) = self.want_to_visit_value(v1, true, None);
    if v2.is_global() {
        let value_data = self.program.borrow_value(v2).clone();
        let name = value_data.name().unwrap()[1..].to_string();
        codes.extend(self.store_global(reg1, name));
    } else {
        let offset = *self
            .local_value_location
            .get(&v2)
            .expect("assign_v1_to_v2: v2 has no stack location!");
        codes.extend(self.store_with_offset(reg1, offset as isize));
    }
    codes
}

/// Example:
/// getelemptr @a, 114 -> The absolute location of @a in memory.
/// getelemptr %0, 514 -> The value of %0 (which is an address).
fn get_absolute_location(&mut self, value: Value) -> (usize, Vec<String>) {
    if value.is_global() {
        let value_data = self.program.borrow_value(value).clone();
        let name = value_data.name().unwrap()[1..].to_string();
        let (reg, mut codes) = self.get_tmp_reg();
        codes.push(format!("  la\t{}, {}", REGISTER_NAMES[reg], name));
        (reg, codes)
    } else {
        let value_data = self.fd.dfg().value(value).clone();
        match value_data.kind() {
            koopa::ir::ValueKind::Alloc(_) => {
                let offset = *self
                    .local_value_location
                    .get(&value)
                    .expect("get_absolute_location: alloc has no stack location!");
                let (reg, mut codes) = self.get_tmp_reg();
                codes.extend(self.add_with_offset(reg, offset as isize));
                (reg, codes)
            }
            // The value itself is an address.
            _ => self.want_to_visit_value(value, true, None),
        }
    }
}

